    minc = min(c for r,c in cuepts.values()); maxc = max(c for r,c in cuepts.values())
    target = {color: _corner(r-minr, c-minc, maxr-minr+1, maxc-minc+1)
              for color,(r,c) in cuepts.items()}

    best, bestscore = panel, -1
    for v in _variants(panel):
